from jifunze_lab import lnd

MULTIPLIER = {"m": 10**-3, "u": 10**-6, "n": 10**-9, "p": 10**-12}


def amount_sats(invoice: str) -> int:
    hrp = invoice[: invoice.rfind("1")]
    for prefix in ("lnbcrt", "lntbs", "lntb", "lnbc"):
        if hrp.startswith(prefix):
            amount = hrp[len(prefix):]
            break
    if amount and amount[-1] in MULTIPLIER:
        btc = int(amount[:-1]) * MULTIPLIER[amount[-1]]
    else:
        btc = int(amount or 0)
    return round(btc * 100_000_000)


invoice = lnd("dina").addinvoice(50000, "kitabu")["payment_request"]
print("my decoder:", amount_sats(invoice), "sats")
print("lnd says: ", lnd("dina").decode(invoice)["num_satoshis"], "sats")
